TRANSLATIONS.update(EMAIL_TRANSLATIONS)


def seed(db: Session, tenant_id) -> int:
    """Importable desde routers/superadmin.py (alta de tenant) además del
    CLI de abajo. No usa el ORM (raw INSERT) por rendimiento con ~800 filas
    — por eso `tenant_id` va explícito en el statement en vez de depender
    del autofill de app/tenancy.py, que solo cubre inserts ORM."""
    inserted = 0
    for key, langs in TRANSLATIONS.items():
        for lang, value in langs.items():
            db.execute(
                text("""
                    INSERT INTO translations (id, tenant_id, key, lang, value)
                    VALUES (gen_random_uuid(), :tenant_id, :key, :lang, :value)
                    ON CONFLICT (tenant_id, key, lang) DO UPDATE SET value = EXCLUDED.value
                """),
                {"tenant_id": str(tenant_id), "key": key, "lang": lang, "value": value},
            )
            inserted += 1
    return inserted


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--tenant", required=True, help="Slug del tenant (ver tabla tenants)")
    args = parser.parse_args()

    db = SessionLocal()
    try:
        tenant = db.scalar(select(Tenant).where(Tenant.slug == args.tenant))
        if tenant is None:
            raise SystemExit(f"No existe ningún tenant con slug '{args.tenant}'")
        inserted = seed(db, tenant.id)
        db.commit()
        print(f"Done: {inserted} translations upserted ({len(TRANSLATIONS)} keys × 3 langs) para tenant '{args.tenant}'.")
    finally:
        db.close()


if __name__ == "__main__":
    main()
